import { Page } from '@playwright/test';

/**
 * Page Object — Katalon Shop – Katalon Ecommerce.
 * https://cms.demo.katalon.com/
 *
 * Generated by the Zennx Playwright studio from a recorded session.
 * Locators live here and nowhere else, so a renamed button is one edit.
 *
 * 1 locator here is structural or matched more than
 * one element when recorded — the ones that will break first:
 *   img — locator('ul > li:nth-of-type(2) > div > a:nth-of-type(1) > img')
 * Give them a data-testid or an accessible name and re-record.
 */
export class HomePage {
    readonly page: Page;

    private readonly img = () => this.page.locator('ul > li:nth-of-type(2) > div > a:nth-of-type(1) > img');

    constructor(page: Page) {
        this.page = page;
    }

    /** Open this page directly. */
    async goto(): Promise<void> {
        await this.page.goto('https://cms.demo.katalon.com/');
    }

    async clickImg(): Promise<void> {
        await this.img().click();
    }
}
